N, V = map(int, input().split())
W = list(map(int, input().split()))
A = [-1000000000] * V
ans = 0
for k in range(N):
  for v in range(V):
    if v + k + 1 <= V:
      ans = max(ans, A[v] + W[k])
  for i in range(k):
    v = i + k + 2
    if v < V:
      A[v] = max(A[v], W[i] + W[k])
print(ans)
